prompt --application/shared_components/user_interface/templates/list/peek_nav
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(613597780513361377)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TPeekNav #COMPONENT_CSS_CLASSES#" id="#LIST_ID#" data-loading="Loading preview" data-unavailable="Preview not available for this page" data-save-data="Live preview is off to save data" data-hint="Click to open, Esc to close">',
'<ul class="amc-TPeekNav-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>'))
,p_list_template_current=>'<li class="amc-TPeekNav-item is-current"><a class="amc-TPeekNav-link" href="#LINK#" aria-current="page" data-peek="#A02#"><span class="amc-TPeekNav-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TPeekNav-text"><span class="amc-TPeekNav-label">#TEXT#</span><span class="amc-TPeekNav-desc">#A01#</span></span></a><button type="button" class="amc-TPeekNav-eye" aria-label="Preview #TEXT_ESC_SC#" aria-expanded="false" hidden><span class="amc-TPeekNav-eyeIcon fa fa-eye" aria-hidden="true"></span></button></li>'
,p_list_template_noncurrent=>'<li class="amc-TPeekNav-item"><a class="amc-TPeekNav-link" href="#LINK#" data-peek="#A02#"><span class="amc-TPeekNav-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TPeekNav-text"><span class="amc-TPeekNav-label">#TEXT#</span><span class="amc-TPeekNav-desc">#A01#</span></span></a><button type="button" class="amc-TPeekNav-eye" aria-label="Preview #TEXT_ESC_SC#" aria-expanded="false" hidden><span class="amc-TPeekNav-eyeIcon fa fa-eye" aria-hidden="true"></span></button></li>'
,p_list_template_name=>'AMC Peek Nav'
,p_internal_name=>'AMC_TPL_PEEK_NAV'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-peek-nav.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-peek-nav.css'
,p_a01_label=>'Description'
,p_a02_label=>'Preview URL or none'
,p_list_template_comment=>'List template for a static or dynamic List region, flat lists. Each entry is a real link with its icon and label; User Defined Attribute 1 is a one-line description, shown on the preview card and, with the Show descriptions option, under the label. Attribute 2 is optional: a developer-controlled preview URL that replaces the link for the preview only (for example a lighter page made for previews), or the word none to switch the preview off for that entry. With JavaScript, resting the mouse on an entry for about half a second opens one floating preview card: title, page path, a live same-origin view of the target page scaled down in a sandboxed iframe that cannot be clicked or focused and is hidden from screen readers, a skeleton while it loads, and the description. Moving to another entry switches the card at once; leaving the entry and the card, pressing Escape, clicking the link, scrolling or resizing closes it. Only one card is open at a time, and the last 3 previews are kept loaded so going back is instant. Keyboard users press the eye button after each link, a real button with aria-expanded, to open or close the card; Escape closes it. Clicking the card opens the page. No preview is made for external links, javascript links, links to the current page or entries with Attribute 2 set to none, and nothing is ever shown on touch screens. When the browser asks to save data, via Save-Data or prefers-reduced-data, the card shows the description without the live view. A page loaded in the preview runs as a normal page request in the user''s session, so do not use it for pages whose load processes change data, and set the page''s Embed in Frames security attribute to Allow from same origin. Without JavaScript the list is a plain, fully working navigation list. Template options: Preview on click of the eye button only; Description card only; Show descriptions; Horizontal bar; Large preview. Under prefers-reduced-motion the card appears without animation and the skeleton does not shimmer. English strings to translate: in the entry parts the eye button label Preview followed by the entry text; on the wrapper in the Before List Entry part data-loading Loading preview, data-unavailable Preview not available for this page, data-save-data Live preview is off to save data, data-hint Click to open, Esc to close.'
);
end;
/
begin
wwv_flow_imp_shared.create_template_option(
 p_id=>wwv_flow_imp.id(502981918710468954)
,p_theme_id=>42
,p_name=>'EYE_ONLY'
,p_display_name=>'Preview on click of the eye button only'
,p_display_sequence=>10
,p_list_template_id=>wwv_flow_imp.id(613597780513361377)
,p_css_classes=>'amc-TPeekNav--eyeOnly'
,p_template_types=>'LIST'
,p_help_text=>'Resting the mouse on an entry does nothing; previews open only from the eye button, which is always visible. Use it for dense menus people move through quickly.'
);
end;
/
